use base64::{Engine as _, engine::general_purpose::STANDARD};

// Compact-ICC-Profiles is CC0. Elle Stone's linear/ACES profiles are CC BY-SA 3.0.
const SRGB: &str = "";
const PROPHOTO: &str = "";
const REC2020: &str = "";
const ACES: &str = "";
const SRGB_LINEAR: &str = "";
const PROPHOTO_LINEAR: &str = "";
const REC2020_LINEAR: &str = "";

pub fn profile(color_space: &str, encoded: bool) -> Vec<u8> {
    let value = match (color_space, encoded) {
        ("ProPhoto RGB", true) => PROPHOTO,
        ("ProPhoto RGB", false) => PROPHOTO_LINEAR,
        ("Rec. 2020" | "Rec2020" | "ITU-R BT.2020", true) => REC2020,
        ("Rec. 2020" | "Rec2020" | "ITU-R BT.2020", false) => REC2020_LINEAR,
        ("ACES2065-1", _) => ACES,
        (_, true) => SRGB,
        (_, false) => SRGB_LINEAR,
    };
    STANDARD
        .decode(value)
        .expect("embedded ICC profile is valid")
}
